item.aggregated_output:
args <- commandArgs(trailingOnly = TRUE)
h5ad_path <- args[[1]]
out_report <- args[[2]]

suppressPackageStartupMessages(library(Matrix))

url <- "https://ftp.ncbi.nlm.nih.gov/geo/series/GSE132nnn/GSE132730/suppl/GSE132730_RAW.tar"
member <- "GSM3890934_Hypothalamus_traject_E15_srt_annotated_wo_blood.rds.gz"

cmd <- sprintf("curl -fsSL %s | tar -xOf - %s > source.rds.gz", shQuote(url), shQuote(member))
status <- system(cmd)
if (!identical(status, 0L)) {
  stop(sprintf("source extraction failed with status %s", status))
}

gunzip_status <- system("gzip -dc source.rds.gz > source_inner.rds.gz")
if (!identical(gunzip_status, 0L)) {
  stop(sprintf("inner gzip extraction failed with status %s", gunzip_status))
}
obj <- readRDS(gzfile("source_inner.rds.gz"))

obj_attrs <- attributes(obj)
summ <- list(
  source_url = url,
  source_member = member,
  object_class_attr = obj_attrs$class,
  object_attribute_names = names(obj_attrs)
)

matrix_summary <- function(x) {
  list(
    class = class(x),
    dim = dim(x),
    nnz = if (inherits(x, "sparseMatrix")) length(x@x) else NA_integer_,
    total_counts = if (is.numeric(x)) as.numeric(sum(x)) else NA_real_,
    row_first = head(rownames(x), 20),
    row_last = tail(rownames(x), 20),
    col_first = head(colnames(x), 20),
    col_last = tail(colnames(x), 20)
  )
}

try_add_matrix <- function(name, x) {
  out <- tryCatch(matrix_summary(x), error = function(e) list(error = conditionMessage(e)))
  summ[[name]] <<- out
}

if (!is.null(obj_attrs$assays)) {
    assays <- obj_attrs$assays
    summ$assay_names <- names(assays)
    for (assay_name in names(assays)) {
      assay <- assays[[assay_name]]
      assay_attrs <- attributes(assay)
      if (!is.null(assay_attrs)) {
        assay_slots <- names(assay_attrs)
        summ[[paste0("assay_", assay_name, "_attributes")]] <- assay_slots
        for (slot_name in intersect(c("counts", "data", "scale.data", "raw.data"), assay_slots)) {
          val <- assay_attrs[[slot_name]]
          if (!is.null(val)) {
            try_add_matrix(paste0("assay_", assay_name, "_", slot_name), val)
          }
        }
      }
    }
}
for (slot_name in intersect(c("raw.data", "data", "scale.data", "meta.data"), names(obj_attrs))) {
    val <- obj_attrs[[slot_name]]
    if (!is.null(val)) {
      if (inherits(val, "Matrix") || is.matrix(val)) {
        try_add_matrix(paste0("slot_", slot_name), val)
      } else {
        summ[[paste0("slot_", slot_name, "_class")]] <- class(val)
        summ[[paste0("slot_", slot_name, "_dim")]] <- dim(val)
        summ[[paste0("slot_", slot_name, "_names")]] <- names(val)
        summ[[paste0("slot_", slot_name, "_rownames_first")]] <- head(rownames(val), 20)
      }
    }
}

sink(out_report)
str(summ, max.level = 4, vec.len = 25)
sink()

